-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'Introdução à Tecnologia da Informação e Comunicação' and a.numero = 7
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 7 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Atividade Individual — Discursivas', 'PENDENTE', v_aula, 'Atividade — Atividade Individual — Discursivas (30 questões discursivas)',
      '/MATERIAIS/ASSISTENTE-DE-OPERACOES-LOGISTICAS/INTRODUCAO-TIC/ATIVIDADES/ATIVIDADE-SEXTA-FEIRA/ATIVIDADE-INDIVIDUAL-COMUNICACAO-TECNICA-DISCURSIVA.html', 30, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Identificação dos cinco elementos na situação.', 1.0, 'Emissor: o supervisor do CD. Receptor: o operador da separação. Mensagem: o pedido 1520 é de sabão em pó, não de detergente. Canal: o rádio. Feedback: a resposta "Entendido, vou trocar".', 'Nota cheia: os cinco elementos corretos. Metade: três ou quatro corretos. Zero: dois ou menos.'),
      (v_atividade, 2, 1, 'Conceito de ruído, relação com a situação e atitude preventiva.', 1.0, 'Ruído é tudo o que atrapalha a mensagem a chegar como o emissor quis (barulho, falta de atenção, palavra ambígua). Na situação, a divisão das tarefas não foi entendida igual por todos. Atitudes: registrar os papéis na ata, repetir/confirmar quem faz cada texto, pedir feedback no fim da reunião.', 'Nota cheia: conceito, relação com o caso e uma atitude coerente. Metade: dois desses três. Zero: um ou nenhum.'),
      (v_atividade, 3, 1, 'Comentário assertivo e explicação.', 1.0, 'Ex.: "Sugiro trocar ''muitos pedidos'' por ''38 dos 150 pedidos'' e ''umas máquinas'' por ''2 dos 6 coletores de dados'', para o gerente entender o tamanho do problema." É assertivo porque é claro, específico, respeitoso e propõe uma solução, sem ofender nem deixar de apontar o erro.', 'Nota cheia: comentário específico, cordial, com sugestão e explicação correta. Metade: comentário adequado sem explicação, ou explicação sem comentário adequado. Zero: comentário agressivo/vago ou em branco.'),
      (v_atividade, 4, 1, 'Conceito de consenso, como buscá-lo e justificativa dos papéis.', 1.0, 'Consenso não é todos pensarem igual: é todos serem ouvidos e concordarem em apoiar a decisão final. Para buscá-lo: ouvir todos, comparar as alternativas por critérios objetivos (prazo, custo, segurança) e combinar uma decisão que todos apoiem. Cada um precisa saber o seu papel, informar o andamento e avisar impedimentos cedo, para evitar o "achei que você já tinha feito" (cap. 01 e 04).', 'Nota cheia: conceito de consenso, como buscá-lo e justificativa dos papéis. Metade: dois desses três. Zero: um ou nenhum.'),
      (v_atividade, 5, 1, 'Ata em parágrafo único, com abertura, decisões e encerramento.', 1.0, 'Ex.: "Aos nove dias do mês de outubro de dois mil e vinte e seis, às treze horas e trinta minutos, na sala 12, reuniram-se Ana, Bruno, Carla e Davi para dividir as tarefas do Manual de Comunicação do CD. Ficou decidido que Ana será a líder e escreverá a ata; Bruno será o pesquisador e escreverá o relatório; Carla será a redatora e escreverá o memorando; Davi será o formatador e escreverá o e-mail. Nada mais havendo, encerrou-se a reunião, e eu, Ana, escrevi esta ata."', 'Nota cheia: texto corrido, abertura (data, hora, local, participantes), decisões, encerramento e verbos no passado. Metade: falta uma dessas partes ou usa tópicos. Zero: não tem forma de ata.'),
      (v_atividade, 6, 1, 'Quatro linhas corretas com horário, setor e problema.', 1.0, '7h30 — Recebimento — 600 caixas guardadas no endereço errado; 8h às 11h — Separação — 38 de 150 pedidos errados; 11h — Armazenagem — 70 caixas de diferença; 13h — Armazenagem — 15 caixas vencidas; 15h — Expedição — 3 horas de atraso; 16h — e-mail falso (phishing).', 'Nota cheia: quatro ou mais linhas com horário, setor e problema corretos. Metade: duas ou três linhas corretas. Zero: uma ou nenhuma.'),
      (v_atividade, 7, 1, 'Parágrafo com as quatro causas, impessoal.', 1.0, 'Causas que aparecem no contexto: o endereço B-03-04 foi trocado por B-04-03 no recebimento; 2 dos 6 coletores de dados pararam de ler o código de barras por problema de driver; as caixas novas de amaciante ficaram na frente das antigas, que venceram; o e-mail falso pediu a senha do sistema. Texto na terceira pessoa, impessoal, com foco no fato e não em quem fez (cap. 07 — impessoalidade).', 'Nota cheia: quatro causas do contexto, terceira pessoa, sem culpar pessoas. Metade: duas ou três causas, ou culpa pessoas. Zero: uma causa ou nenhuma.'),
      (v_atividade, 8, 1, 'Cálculo correto e frase técnica.', 1.0, 'Diferença: 320 − 250 = 70 caixas. Ex.: "No inventário das 11h, foram encontradas 250 das 320 caixas previstas no endereço B-03-04, uma diferença de 70 caixas, provavelmente causada pela troca de endereço no recebimento." Frase objetiva, com números e impessoal (cap. 07).', 'Nota cheia: 70 caixas e frase técnica com número e causa. Metade: só o cálculo ou frase sem número correto. Zero: cálculo errado e sem frase.'),
      (v_atividade, 9, 1, 'Frase de fato com números e frase de recomendação, separadas e impessoais.', 1.0, 'Fato: "Constatou-se o vencimento de 15 caixas de amaciante, guardadas no fundo da prateleira, atrás das caixas novas." Recomendação: "Recomenda-se conferir a validade na arrumação e posicionar à frente as caixas que vencem primeiro." Fato e recomendação separados, com números, na terceira pessoa (cap. 07 — separar fato de recomendação; pilares da redação técnica).', 'Nota cheia: fato com número e recomendação, separados e impessoais. Metade: só um dos dois, ou mistura fato com recomendação. Zero: opinião pessoal ou jargão.'),
      (v_atividade, 10, 1, 'Duas sugestões, cada uma ligada a uma causa.', 1.0, 'Ex.: (1) conferir o endereço no coletor antes de guardar a carga — causa: endereço trocado; (2) instalar ou atualizar o driver dos coletores após cada atualização do sistema — causa: coletores parados; (3) conferir a validade e deixar à frente o que vence primeiro — causa: caixas vencidas; (4) não informar senha por e-mail e avisar o suporte de TI — causa: e-mail falso.', 'Nota cheia: duas sugestões viáveis, cada uma ligada a uma causa do contexto. Metade: uma sugestão ligada, ou duas sem ligação com a causa. Zero: nenhuma sugestão coerente.'),
      (v_atividade, 11, 1, 'Busca, avaliação da fonte e dados da referência.', 1.0, 'Busca: usar aspas para a frase exata, ex.: "inventário rotativo" (pode somar site: ou filetype:). Fonte confiável: aplicar o teste CRAAP (atualidade, relevância, autoridade, precisão, propósito), preferir sites oficiais (.gov.br, .edu.br) e confirmar em pelo menos 3 fontes. Referência no fim: autor, título, site e data de acesso. Escrever com as próprias palavras, citando (cap. 03).', 'Nota cheia: os três elementos corretos. Metade: dois. Zero: um ou nenhum, ou diz para copiar e colar.'),
      (v_atividade, 12, 1, 'Memorando com todas as partes e os dados do caso.', 1.0, 'Ex.: "MEMORANDO Nº 01/2026 — Para: Gerente do CD — De: Setor de TI — Data: 09/10/2026 — Assunto: Pedido de coletores de dados para a separação. Prezado(a) Gerente, solicitamos a compra de 2 coletores de dados, porque 2 dos 6 equipamentos estão parados desde a atualização do sistema (problema de driver), o que fez 38 dos 150 pedidos saírem errados e atrasou a expedição em 3 horas. Pedimos a compra até 16/10/2026. Atenciosamente, [nome] — Técnico de TI."', 'Nota cheia: cabeçalho completo, saudação, pedido com dados, prazo e fecho. Metade: falta uma ou duas partes. Zero: não tem forma de memorando.'),
      (v_atividade, 13, 1, 'Classificação dos três equipamentos com justificativa.', 1.0, 'Pela tabela da apostila (cap. 02): coletor de dados — entrada e saída (lê o código de barras e envia ao sistema, e também mostra informações na tela). Impressora de etiquetas — saída (entrega o resultado impresso). Cartão de memória — armazenamento (guarda os dados de forma permanente). Aceitar "entrada" para o coletor só se a justificativa citar a leitura do código de barras.', 'Nota cheia: três classificações corretas e justificadas. Metade: três corretas sem justificativa, ou duas corretas justificadas. Zero: uma ou nenhuma correta.'),
      (v_atividade, 14, 1, 'Conceito de driver, relação com o problema e ordem de verificação.', 1.0, 'Driver é o programa que permite ao sistema controlar o periférico. Depois da atualização, o driver dos coletores pode precisar ser instalado ou atualizado, por isso o equipamento liga, mas não lê. Ordem de verificação: hardware (cabo e porta; testar outra porta) → driver (aparelho com alerta no Gerenciador de Dispositivos?) → configuração do sistema (o dispositivo está habilitado?) (cap. 02).', 'Nota cheia: os três pontos corretos. Metade: dois. Zero: um ou nenhum.'),
      (v_atividade, 15, 1, 'E-mail completo e adequado ao cliente.', 1.0, 'Ex.: "Para: compras@bompreco-ficticio.com.br — CC: comercial@rotacerta-ficticio.com.br — Assunto: Troca do pedido nº 1520 — sabão em pó. Prezados, pedimos desculpas pelo envio de detergente no lugar de sabão em pó. Houve uma falha na separação do pedido. O produto correto será entregue em 10/10/2026, e o produto enviado por engano será recolhido na mesma entrega. Atenciosamente, [nome] — Atendimento — Rota Certa Logística e Armazenagem."', 'Nota cheia: todos os campos, tom cordial, sem culpar colegas, solução com data, e-mails fictícios. Metade: faltam até dois campos ou a data. Zero: tom inadequado, culpa pessoas ou usa e-mail real.'),
      (v_atividade, 16, 1, 'Função do CC e justificativa sobre a frase.', 1.0, 'CC (com cópia) envia o e-mail também para quem precisa saber do assunto sem ser o destinatário principal; o comercial acompanha a reclamação e a solução do cliente. A frase não deve ser usada porque expõe e culpa um colega, mostra detalhes internos e passa má imagem da empresa; o certo é falar da falha no processo ("houve uma falha na separação").', 'Nota cheia: os dois pontos corretos. Metade: um. Zero: nenhum.'),
      (v_atividade, 17, 1, 'Conceito, dois sinais e conduta correta.', 1.0, 'Phishing é uma mensagem falsa que finge ser de alguém confiável para roubar dados (senhas). Sinais: pede a senha (o suporte nunca pede), urgência/pressa, remetente estranho, erros, links suspeitos. Conduta: não responder, não clicar, não passar a senha, avisar o TI/supervisor e apagar ou reportar o e-mail.', 'Nota cheia: conceito, dois sinais e conduta correta. Metade: dois desses três. Zero: um ou nenhum, ou diz que passaria a senha.'),
      (v_atividade, 18, 1, 'Quatro regras com verbo de ordem e frase de atenção.', 1.0, 'Ex.: 1. Crie senha forte, de 12 a 16 caracteres, com letras maiúsculas e minúsculas, números e símbolos, e não a repita em outros sistemas. 2. Ative a autenticação em dois fatores (2FA). 3. Bloqueie a tela ao sair da mesa (Windows + L). 4. Faça backup periódico na nuvem da empresa. ATENÇÃO: nunca informe sua senha por e-mail (cap. 05).', 'Nota cheia: quatro regras corretas, verbos de ordem, lista numerada e frase de atenção. Metade: três regras ou sem a frase de atenção. Zero: duas regras ou menos.'),
      (v_atividade, 19, 1, 'Três regras corretas e para que serve cada uma.', 1.0, 'Margens no padrão ABNT: 3 cm em cima e à esquerda, 2 cm embaixo e à direita (espaço entre o texto e a borda). Estilos Título 1 (seções) e Título 2 (subseções): padronizam os títulos e geram o sumário automático (menu Referências ou Inserir), que deve ser atualizado depois de editar. Quebra de página: começa o próximo texto numa página nova sem apertar vários Enter. Número da página no rodapé (cabeçalho e rodapé) (cap. 06).', 'Nota cheia: três regras corretas e para que serve cada uma. Metade: três regras sem a finalidade, ou duas com a finalidade. Zero: uma ou nenhuma correta.'),
      (v_atividade, 20, 1, 'Introdução com contexto, números e objetivo, impessoal.', 1.0, 'Ex.: "A Rota Certa Logística e Armazenagem (empresa fictícia) registrou, na segunda-feira, falhas em seu centro de distribuição: 38 dos 150 pedidos saíram errados, faltaram 70 caixas no inventário, 15 caixas venceram e a expedição atrasou 3 horas, com prejuízo de cerca de R$ 4.200. Este manual tem o objetivo de registrar o ocorrido e padronizar a comunicação do CD." Introdução = contexto e objetivo (cap. 07, ABNT NBR 10719), na terceira pessoa.', 'Nota cheia: empresa, problema com números e objetivo, na terceira pessoa. Metade: falta uma parte ou não usa números. Zero: falta mais de uma parte.'),
      (v_atividade, 21, 1, 'RAM volátil × armazenamento permanente e conduta correta.', 1.0, 'A contagem estava só na memória RAM, que guarda o que está em uso e é volátil: ao desligar (ou faltar energia), perde tudo. Quem guarda de forma permanente é o HDD ou o SSD. Ele deveria ter salvado o arquivo com frequência (cap. 02).', 'Nota cheia: RAM volátil, armazenamento permanente e conduta (salvar). Metade: dois desses três. Zero: um ou nenhum.'),
      (v_atividade, 22, 1, 'Três tarefas do SO e o tipo de SO dos coletores com exemplo.', 1.0, 'O SO gerencia processos (divide o tempo do processador entre os programas), a memória (reserva espaço da RAM para cada programa) e os arquivos (organiza e protege o que é gravado). Coletores de dados usam SO móvel, como Android ou iOS (cap. 02).', 'Nota cheia: três tarefas e tipo móvel com exemplo. Metade: duas tarefas e tipo correto, ou três tarefas sem o tipo. Zero: uma tarefa ou nenhuma.'),
      (v_atividade, 23, 1, 'Diferença entre internet e web e avaliação da afirmação.', 1.0, 'A internet é a infraestrutura (cabos, roteadores, servidores, protocolos TCP/IP); a web é um serviço que funciona sobre ela, com páginas ligadas por links, criada por Tim Berners-Lee no CERN em 1989. A afirmação está errada: são coisas diferentes, e aplicativos de mensagem usam a internet, mas não são a web (cap. 03).', 'Nota cheia: diferença correta e afirmação avaliada como errada com justificativa. Metade: só um dos dois. Zero: diz que são a mesma coisa.'),
      (v_atividade, 24, 1, 'Plágio, Lei 9.610/98 e regras das citações direta e indireta.', 1.0, 'É plágio porque apresenta como seu o trabalho de outra pessoa, copiando sem citar. A Lei 9.610/98 protege os direitos autorais; estar na internet não libera a cópia. Citação direta: palavras exatas entre aspas, com autor, ano e página (SILVA, 2023, p. 15). Citação indireta: a ideia com as próprias palavras, sem aspas, com autor e ano (Para Silva (2023), ...). No fim, as referências completas (cap. 03).', 'Nota cheia: plágio, lei e as duas citações corretas. Metade: dois desses três. Zero: um ou nenhum.'),
      (v_atividade, 25, 1, 'Problema da escolha, LGPD e uso correto de Para, CC e CCO.', 1.0, 'Com todos em "Para", cada cliente vê o e-mail dos outros: expõe dados pessoais e pode violar a LGPD. Correto: os 40 clientes em CCO (cópia oculta); em "Para" o próprio remetente ou o setor, e em CC quem só precisa acompanhar (ex.: supervisor) (cap. 04).', 'Nota cheia: problema + LGPD e uso correto dos três campos. Metade: problema explicado e só o CCO indicado. Zero: mantém todos em Para ou CC.'),
      (v_atividade, 26, 1, 'Três permissões corretas e risco do link público de edição.', 1.0, 'Transportadora: leitor (só ver e baixar). Auditoria: comentador (ver e comentar). Colegas da expedição: editor (alterar). Link público de edição deixa qualquer pessoa com o link apagar ou alterar os arquivos; compartilhar com os e-mails das pessoas certas e revisar os acessos (cap. 04).', 'Nota cheia: três permissões e risco do link público. Metade: duas permissões e o risco, ou três sem o risco. Zero: uma ou nenhuma.'),
      (v_atividade, 27, 1, 'Três relações corretas e o que cada pilar garante.', 1.0, '(a) Confidencialidade — só quem tem autorização acessa. (b) Integridade — a informação não é alterada indevidamente. (c) Disponibilidade — a informação está acessível quando precisa (cap. 05).', 'Nota cheia: três relações e o que cada pilar garante. Metade: três relações sem explicação, ou duas com explicação. Zero: uma ou nenhuma.'),
      (v_atividade, 28, 1, 'Conceito de ransomware, risco do pagamento e plano 3-2-1.', 1.0, 'Ransomware criptografa os arquivos e pede resgate; pagar não garante a devolução. Backup 3-2-1: 3 cópias dos dados (a original + 2), em 2 tipos de mídia diferentes (ex.: servidor e disco externo) e 1 cópia fora da empresa (ex.: nuvem corporativa); testar a restauração de vez em quando (cap. 05).', 'Nota cheia: conceito, risco do pagamento e plano 3-2-1 completo. Metade: dois desses três. Zero: um ou nenhum.'),
      (v_atividade, 29, 1, 'Estilos, numeração, marcadores e aviso com borda e sombreamento.', 1.0, 'Aplicar Título 1 às seções e Título 2 às subseções (permite o sumário automático); lista numerada nos passos do recebimento (têm ordem); marcadores na lista de EPIs (sem ordem); aviso de segurança em caixa com borda e sombreamento suave, legível em preto e branco (cap. 06).', 'Nota cheia: estilos, numeração, marcadores e destaque do aviso. Metade: dois ou três desses itens. Zero: um ou nenhum.'),
      (v_atividade, 30, 1, 'Aceitar/rejeitar e apagar comentários, nome padronizado e envio em PDF.', 1.0, 'Aceitar ou rejeitar todas as alterações e apagar os comentários internos (são confidenciais); renomear no padrão, ex.: 2026-10-14_Relatorio_Avaria_v01; enviar em PDF, versão final sem edição; visualizar a impressão antes (cap. 06).', 'Nota cheia: alterações/comentários, nome padronizado e PDF, com justificativa. Metade: dois desses três. Zero: um ou nenhum.');
end $$;
